/// Each method's name, as called.
pub mod method {
    /// The connection handshake; answered to a member or a bot without paths, addresses, backends or screen state, with the agents they hold.
    pub const HELLO: &str = "hello";
    /// An agent's card, for a chat that is theirs.
    pub const KITH_INFO: &str = "kithInfo";
    /// Their own chat with an agent they hold, one per agent: made on first use.
    pub const START_CHAT: &str = "startChat";
    /// A message in their own chat. attachments are upload ids; pasted is what was pasted rather than typed. A new thread starts in project (for a member, one shared with them); folder and clear are the owner's and refused to a member. budget (a group only) is how many agent turns the message may cause, rounds included; default 10.
    pub const SEND: &str = "send";
    /// A thread's replies (its newest 500); the root is in the main chat.
    pub const THREAD: &str = "thread";
    /// A page of the main chat, newest first before beforeSeq.
    pub const HISTORY: &str = "history";
    /// The agent starts a new session.
    pub const NEW_SESSION: &str = "newSession";
    /// Takes back a message that still waits for its turn.
    pub const UNSEND: &str = "unsend";
    /// Marks the chat read, or the thread threadId; all marks every place.
    pub const MARK_READ: &str = "markRead";
    /// Stops the turn where the user pressed it: the chat, or the thread threadId; all stops the bot everywhere.
    pub const STOP: &str = "stop";
    /// One chunk of a file for a later send, through the chat's own upload folder: base64 data at offset.
    pub const UPLOAD: &str = "upload";
    /// A sent file, back in chunks (chat previews on other devices).
    pub const READ_UPLOAD: &str = "readUpload";
    /// Toggles one emoji on an entry of their own chat.
    pub const REACT: &str = "react";
    /// Answers an agent's permission card in their own chat; only a member of that agent may (a guest's go to the owner).
    pub const RESPOND_PERMISSION: &str = "respondPermission";
    /// Edits a handoff card's text while it is a draft.
    pub const EDIT_HANDOFF: &str = "editHandoff";
    /// Keeps the conversation a handoff card offered to move on from.
    pub const KEEP_CONVERSATION: &str = "keepConversation";
    /// Only the project folders the owner shared with them.
    pub const PROJECTS: &str = "projects";
    /// The project of their own chat's thread (threadId; the main chat without it).
    pub const THREAD_PROJECTS: &str = "threadProjects";
    /// Corrects their own chat's thread's project set, to projects shared with them; an empty list is no project.
    pub const SET_THREAD_PROJECTS: &str = "setThreadProjects";
    /// The code that links their own Telegram, Discord or Slack account to their person.
    pub const LINK_CODE: &str = "linkCode";
    /// Whether their own Schedule cards are also said in their Telegram, Discord or Slack chat with the agent (on unless they turn it off), set first when on is given. The card in the app and a run's own messages stay either way.
    pub const SCHEDULE_MESSAGES: &str = "scheduleMessages";
    /// Answers an incoming call from their own agent; the host checks the call is theirs.
    pub const CALL_ACCEPT: &str = "callAccept";
    /// Declines an incoming call from their own agent.
    pub const CALL_DECLINE: &str = "callDecline";
    /// The call is up: the agent says what it called about.
    pub const CALL_GREET: &str = "callGreet";
    /// The app logs the end of a call it took as a line in the chat (frees the person for the next call).
    pub const LOG_CALL: &str = "logCall";
    /// A call that just connected: its line goes in the chat now; endCall fills in its length.
    pub const START_CALL: &str = "startCall";
    /// The call's end: its length on its line (entryId), or, for a call that never connected, only freeing the person.
    pub const END_CALL: &str = "endCall";
    /// Invites a bot guest from what they hold (docs/kith-bot-guests.md), or a new invite for their bot botId.
    pub const CREATE_BOT_INVITE: &str = "createBotInvite";
    /// Revokes an invite of one of their bots.
    pub const REVOKE_BOT_INVITE: &str = "revokeBotInvite";
    /// Removes one of their bots.
    pub const REVOKE_BOT: &str = "revokeBot";
    /// Their own bot guests, newest first.
    pub const MY_BOTS: &str = "myBots";
    /// One of their bots' limits; a limit left out stays. turnTimeoutS is clamped to 30 to 3600. wakeProfile (the computer's owner only) is a kith-auth profile name for the grok service; an empty string clears it.
    pub const SET_BOT_LIMITS: &str = "setBotLimits";
    /// A kith://thread/<id>#entry=<seq> link: the thread when it is theirs, else a stable not_shared.
    pub const RESOLVE_CITATION: &str = "resolveCitation";
    /// All an invited person's unproven device may call: showing the invite's token.
    pub const PROVE_INVITE: &str = "proveInvite";
    /// A bot's own state, owner and agents; also while it waits to be allowed.
    pub const BOT_STATUS: &str = "botStatus";
    /// A bot's new key shows the invite token from its link, which the cloud never saw; until then it can call nothing else. Proving twice is fine.
    pub const PROVE_BOT_INVITE: &str = "proveBotInvite";
    /// Asks an agent in a conversation of the bot's own, made on first use (agent names it then). clientNonce makes a retry safe. room (a room this bot is a member of) turns the ask into one turn of the agent it @-mentions there: no conversation opens, the agent's reply wakes nobody, and an open conversation's budget is charged.
    pub const BOT_ASK: &str = "botAsk";
    /// Posts into a room the bot is a member of. conversation and epoch say which turn it answers; with the turnKey of the turn the room is waiting on it is the member's reply, without one it is an unprompted post (charged one turn; wakes only the members it @-mentions, only while the conversation is open with budget left). Anything else is kept as late and wakes nobody. clientNonce makes a retry post once; the same nonce with other text is nonceReused. A post never opens or tops up a budget. A room the bot is not in is notFound.
    pub const BOT_POST: &str = "botPost";
    /// What a bot member may read of a room: its entries after the cursor, shaped as for a bot, with the newest conversation and epoch to post under. A room the bot is not in is notFound.
    pub const BOT_ROOM_READ: &str = "botRoomRead";
    /// What a bot may read of its own conversation, after afterSeq.
    pub const BOT_THREAD: &str = "botThread";
    /// A bot's own conversations, newest first.
    pub const BOT_CONVERSATIONS: &str = "botConversations";
    /// Stops the running turn of the bot's own conversation, and the asks waiting behind it.
    pub const BOT_STOP: &str = "botStop";
    /// The bot retires itself, as if its owner removed it.
    pub const BOT_LEAVE: &str = "botLeave";
    /// The agents another computer of the owner's may ask here (Mac link): the owner's own, by name.
    pub const PEER_AGENTS: &str = "peerAgents";
}

